import '@servicenow/sdk/global'
import { StringColumn } from '@servicenow/sdk/core'
import { Subflow, wfa } from '@servicenow/sdk/automation'

/**
 * Test subflow for AssignSubflowOutputs validation - invalid schema argument
 * Should fail: Second argument must be params.outputs
 */
export const assignSubflowOutputsInvalidSchema = Subflow(
    {
        $id: Now.ID['assign-subflow-outputs-invalid-schema'],
        name: 'AssignSubflowOutputs Invalid Schema Test',
        description: 'Test AssignSubflowOutputs validation with invalid schema argument',
        inputs: {
            inputData: StringColumn({
                label: 'Input Data',
                mandatory: true,
            }),
        },
        outputs: {
            result: StringColumn({
                label: 'Result',
                mandatory: true,
            }),
        },
    },
    (params) => {
        // This should fail validation: wrong schema argument (should be params.outputs, not params.inputs)
        wfa.flowLogic.assignSubflowOutputs(
            {
                $id: Now.ID['assign-outputs-invalid-schema'],
                annotation: 'Invalid: wrong schema argument',
            },
            params.inputs as any, // Invalid: should be params.outputs
            {
                result: 'success',
            }
        )
    }
)
